#pragma once

#include <cstdint>

// The treasure chests of the world map (not those inside shrines and Divine Beasts). The tables are in
// ChestData.cpp, generated by tools/gen_chests.py.
namespace Data
{
    // What kind of thing a chest holds: as much as the card tells before the item itself is asked for.
    enum class ChestContents : uint8_t
    {
        Weapon,
        Bow,
        Shield,
        Armor,
        Arrows,
        Mineral,
        Rupees,
        Material,
        HorseGear,
        KeyItem,
        Count
    };

    enum ChestFlag : uint8_t
    {
        ChestMasterModeOnly = 1, // does not exist in Normal Mode
        ChestDlc = 2,            // comes with the Expansion Pass
        ChestEnemyCamp = 4,      // unlocks when the enemies of its camp are defeated
        ChestSideQuest = 8       // only shows up during a side quest
    };

    struct Chest
    {
        uint32_t hash; // CRC32 of its flag, MainField_<actor>_<hash id>: set when the chest is opened
        float x;
        float y;       // the game's z, like the other objects
        uint8_t flags; // ChestFlag
        uint8_t contents; // ChestContents
        uint16_t item; // index into ChestItemNames
    };

    // Chests with armor, a key item, horse gear or a weapon found in at most two chests are "special".
    extern const Chest Chests[];
    extern const int ChestsCount;
    extern const Chest SpecialChests[];
    extern const int SpecialChestsCount;
    extern const char* const ChestItemNames[];
    extern const int ChestItemNamesCount;

    // Each kind draws with its own icon.
    struct ChestIcon {};
    struct SpecialChestIcon {};
}
